#!/usr/bin/env python3
"""Fill project_proposal_template.hwpx with data from project_proposal.json.

This script:
- extracts the HWPX (ZIP) template
- replaces {{placeholders}} in XML
  * robust to placeholders split across multiple <hp:t> / runs by operating at
    the full paragraph-text level and collapsing to a single <hp:t>
- appends month spans to phase lines (1단계/2단계/3단계)
- removes stale layout cache elements (e.g., <hp:linesegarray>) in modified
  paragraphs to avoid overlapping characters when opened
- re-packs to /root/project_proposal_ready.hwpx
"""

from __future__ import annotations

import json
import os
import re
import shutil
import zipfile
import xml.etree.ElementTree as ET


ROOT_DIR = "/root"
TEMPLATE_PATH = os.path.join(ROOT_DIR, "project_proposal_template.hwpx")
DATA_PATH = os.path.join(ROOT_DIR, "project_proposal.json")
OUT_PATH = os.path.join(ROOT_DIR, "project_proposal_ready.hwpx")

WORK_DIR = "/tmp/hwpx_work"
EXTRACT_DIR = os.path.join(WORK_DIR, "template_contents")


PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")


def _localname(tag: str) -> str:
    # ElementTree uses '{ns}local' for namespaced tags.
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def _build_parent_map(root: ET.Element) -> dict[ET.Element, ET.Element]:
    parent: dict[ET.Element, ET.Element] = {}
    for p in root.iter():
        for c in list(p):
            parent[c] = p
    return parent


def load_data(path: str) -> dict[str, str]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    mapping: dict[str, str] = {}
    for k, v in data.items():
        if v is None:
            mapping[str(k)] = ""
        else:
            mapping[str(k)] = str(v)

    # Budget normalization: remove commas but keep leading currency symbol.
    if "예산" in mapping:
        mapping["예산"] = mapping["예산"].replace(",", "")

    return mapping


def replace_placeholders(text: str, mapping: dict[str, str]) -> str:
    def repl(m: re.Match[str]) -> str:
        key = m.group(1).strip()
        if key in mapping:
            return mapping[key]
        return m.group(0)  # leave untouched if unknown

    return PLACEHOLDER_RE.sub(repl, text)


_YM_RE = re.compile(r"(?P<y>\d{4})[.\-](?P<m>\d{2})")


def _parse_year_month(s: str) -> tuple[int, int] | None:
    m = _YM_RE.search(s)
    if not m:
        return None
    y = int(m.group("y"))
    mo = int(m.group("m"))
    if not (1 <= mo <= 12):
        return None
    return y, mo


def month_span_from_text(date_text: str) -> int | None:
    """Compute inclusive month span from text inside parentheses.

    Examples:
      '2025.01 ~ 2025.03' -> 3
      '2026-08 ~ 2026-10' -> 3
      '2027-01' -> 1
    """
    raw = date_text.strip()
    if "~" in raw:
        left, right = [p.strip() for p in raw.split("~", 1)]
        start = _parse_year_month(left)
        end = _parse_year_month(right)
        if not start or not end:
            return None
        sy, sm = start
        ey, em = end
        return (ey - sy) * 12 + (em - sm) + 1

    single = _parse_year_month(raw)
    if single:
        return 1

    return None


def append_phase_months_if_needed(text: str) -> str:
    # Only apply to the phase lines.
    if not (text.startswith("1단계:") or text.startswith("2단계:") or text.startswith("3단계:")):
        return text

    # Avoid double-appending if script is run twice.
    if re.search(r"\(\d+\s*개월\)", text):
        return text

    # Find the first parenthesized date part.
    m = re.search(r"\(([^)]*)\)", text)
    if not m:
        return text

    span = month_span_from_text(m.group(1))
    if span is None:
        return text

    return f"{text} ({span}개월)"


def collapse_paragraph_text(paragraph: ET.Element, new_text: str, parent_map: dict[ET.Element, ET.Element]) -> None:
    """Set the paragraph's text content to new_text in a single <hp:t>.

    Removes extra <hp:t> nodes (and empty runs left behind).
    """
    t_nodes = [n for n in paragraph.iter() if _localname(n.tag) == "t"]
    if not t_nodes:
        return

    keep = t_nodes[0]
    keep.text = new_text

    # Remove all other <t> nodes.
    for n in t_nodes[1:]:
        p = parent_map.get(n)
        if p is None:
            continue
        try:
            p.remove(n)
        except ValueError:
            pass

    # Remove now-empty <run> nodes except the one that holds 'keep'.
    keep_run = parent_map.get(keep)
    for run in [n for n in paragraph.iter() if _localname(n.tag) == "run"]:
        if run is keep_run:
            continue
        if len(list(run)) == 0 and (run.text is None or run.text == "") and (run.tail is None or run.tail == ""):
            p = parent_map.get(run)
            if p is None:
                continue
            try:
                p.remove(run)
            except ValueError:
                pass


_LAYOUT_CACHE_NAMES = {
    "linesegarray",
    "lineSegArray",
    "linesegArray",
    "LineSeg",
    "lineSeg",
    "lineseg",
}


def remove_layout_cache(paragraph: ET.Element, parent_map: dict[ET.Element, ET.Element]) -> None:
    """Remove layout-cache elements inside a paragraph.

    This prevents overlapping characters when text length changes.
    """
    for el in list(paragraph.iter()):
        if el is paragraph:
            continue
        if _localname(el.tag) in _LAYOUT_CACHE_NAMES:
            p = parent_map.get(el)
            if p is None:
                continue
            try:
                p.remove(el)
            except ValueError:
                pass


def process_xml_file(xml_path: str, mapping: dict[str, str]) -> bool:
    """Return True if the file was modified."""
    tree = ET.parse(xml_path)
    root = tree.getroot()
    parent_map = _build_parent_map(root)

    modified_any = False

    # Operate at paragraph level to handle split placeholders across runs/t nodes.
    for p in [n for n in root.iter() if _localname(n.tag) == "p"]:
        t_nodes = [n for n in p.iter() if _localname(n.tag) == "t"]
        if not t_nodes:
            continue

        original_text = "".join((n.text or "") for n in t_nodes)

        replaced = replace_placeholders(original_text, mapping)
        replaced = append_phase_months_if_needed(replaced)

        if replaced != original_text:
            modified_any = True
            collapse_paragraph_text(p, replaced, parent_map)
            remove_layout_cache(p, parent_map)

    if modified_any:
        tree.write(xml_path, encoding="utf-8", xml_declaration=True)

    return modified_any


def extract_template() -> None:
    if os.path.exists(WORK_DIR):
        shutil.rmtree(WORK_DIR)
    os.makedirs(EXTRACT_DIR, exist_ok=True)

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as z:
        z.extractall(EXTRACT_DIR)


def repack_to_hwpx(out_path: str) -> None:
    if os.path.exists(out_path):
        os.remove(out_path)

    with zipfile.ZipFile(out_path, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for root, dirs, files in os.walk(EXTRACT_DIR):
            dirs.sort()
            files.sort()
            for fn in files:
                full = os.path.join(root, fn)
                rel = os.path.relpath(full, EXTRACT_DIR)
                z.write(full, rel)


def main() -> int:
    if not os.path.exists(TEMPLATE_PATH):
        raise FileNotFoundError(TEMPLATE_PATH)
    if not os.path.exists(DATA_PATH):
        raise FileNotFoundError(DATA_PATH)

    mapping = load_data(DATA_PATH)

    extract_template()

    xml_files: list[str] = []
    for root, _, files in os.walk(EXTRACT_DIR):
        for fn in files:
            if fn.lower().endswith(".xml"):
                xml_files.append(os.path.join(root, fn))

    xml_files.sort()

    modified = 0
    for xp in xml_files:
        if process_xml_file(xp, mapping):
            modified += 1

    repack_to_hwpx(OUT_PATH)

    print(f"Wrote: {OUT_PATH}")
    print(f"XML files modified: {modified}/{len(xml_files)}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

